# ---------------------------------------------------------------------------
# AUTO-GENERATED by Claude Code
# Purpose: the app's settings: a Config class read from services/ui/config.toml, changed while
#          the app runs. A setting is a private variable (None = not set) and a property that
#          returns it or its default. Everything else is derived from the properties, so a new
#          setting needs nothing more: set_config's inputs (which give the Config widget its
#          form and inline AI, widgets.py), the file's keys, config.set_<name>(value) and the
#          debug panel's Config tab.
# To add a setting: in Config, `self.__name: T | None = None` in __init__ and
#          `@property def name(self) -> T:` with a docstring (the form's help text) returning
#          `self.__name or <default>`. Optional: `def check_name(self, value: T) -> None` that
#          raises ValueError to refuse a value. Then use `config.name` where it matters.
# Usage: config.background / config.set_background("~/pics/x.png") /
#        set_config(background=None)
#        (None or "" = back to the default). The file is read again on every use of a setting
#        (no cache, no watcher), so a hand edit applies on the next request.
# ---------------------------------------------------------------------------
from __future__ import annotations

import inspect
import json
import tomllib
import typing
from dataclasses import dataclass
from pathlib import Path
from typing import Any

from pydantic import BaseModel, TypeAdapter, ValidationError, create_model

__all__ = ["CONFIG_FILE", "Config", "Setting", "config", "set_config"]

APP_DIR = Path(__file__).resolve().parents[1]
CONFIG_FILE = APP_DIR / "config.toml"
# Omarchy's link to the current theme's background: this machine's wallpaper
OMARCHY_BACKGROUND = Path.home() / ".local/state/omarchy/current/background"
_HEADER = "\n".join(
    [
        "# AUTO-GENERATED by Claude Code",
        "# delulu-smash's settings (services/ui/ui/config.py). A key left out = its default.",
        "# Written by the Config widget and config.set_<name>(...); a hand edit applies on the next use.",
        "",
    ]
)


@dataclass
class Setting:
    """One setting as the Config tab and the widget show it."""

    name: str
    type: str
    """Its type as written, eg 'Path'."""
    about: str
    """The property's docstring."""
    value: str
    """What the app uses now."""
    is_default: bool
    """Nothing is set for it: `value` is the property's default."""


class Config:
    def __init__(self) -> None:
        self.__background: Path | None = None

    @property
    def background(self) -> Path:
        """The picture the window shows when no panel is open. Default: this machine's
        wallpaper (Omarchy's current background).
        """
        return self.__background or OMARCHY_BACKGROUND

    def check_background(self, value: Path) -> None:
        if not value.is_file():
            raise ValueError(f"no such file: {value}")

    # -- generic: nothing below is edited for a new setting -------------------------------

    def __getattribute__(self, name: str) -> Any:
        # a setting is read from the file as it is now (a hand edit applies on the next use)
        if not name.startswith("_") and name in _NAMES:
            object.__getattribute__(self, "load")()
        return object.__getattribute__(self, name)

    def __getattr__(self, name: str) -> Any:
        # config.set_background(value) = set_config(background=value), for every setting
        if name.startswith("set_") and name.removeprefix("set_") in _NAMES:
            return lambda value: set_config(**{name.removeprefix("set_"): value})
        raise AttributeError(name)

    problem: str = ""
    """Why the file couldn't be used as it is ("" = fine): shown in the Config tab."""

    def _set(self, name: str, value: Any) -> None:
        object.__setattr__(self, f"_Config__{name}", value)

    def _stored(self, name: str) -> Any:
        return object.__getattribute__(self, f"_Config__{name}")

    def load(self) -> None:
        """The file into the private variables. A missing file or key = not set; a file or
        value that can't be read leaves that setting on its default, and `problem` says why.
        """
        problems = []
        try:
            raw = tomllib.loads(CONFIG_FILE.read_text(encoding="utf-8")) if CONFIG_FILE.is_file() else {}
        except (OSError, tomllib.TOMLDecodeError) as error:
            raw, problems = {}, [f"{CONFIG_FILE.name} can't be read ({error}): every setting is on its default"]
        for name in _NAMES:
            try:
                self._set(name, _typed(name, raw[name]) if name in raw else None)
            except ValueError as error:
                self._set(name, None)
                problems.append(f"{name}: {error} (using the default)")
        problems += [f"{key}: not a setting (ignored)" for key in raw if key not in _NAMES]
        object.__setattr__(self, "problem", "; ".join(problems))

    def save(self) -> None:
        """The settings that are set, as the file (the others are left out: their default)."""
        lines = [f"{name} = {_toml(self._stored(name))}" for name in _NAMES if self._stored(name) is not None]
        CONFIG_FILE.write_text(_HEADER + "\n".join(lines) + ("\n" if lines else ""), encoding="utf-8")

    def settings(self) -> list[Setting]:
        """Every setting with what the app uses now, for the Config tab and the widget."""
        self.load()
        return [
            Setting(
                name=name,
                type=getattr(_TYPES[name], "__name__", str(_TYPES[name])),
                about=_ABOUT[name],
                value=_text(object.__getattribute__(self, name)),
                is_default=self._stored(name) is None,
            )
            for name in _NAMES
        ]

    def stored(self) -> dict[str, str]:
        """What is set, as text ("" for a setting on its default): what the widget's form
        starts with, so running it unchanged changes nothing.
        """
        self.load()
        return {name: "" if self._stored(name) is None else _text(self._stored(name)) for name in _NAMES}

    def texts(self) -> dict[str, str]:
        """Every setting's value in use, as text: what the page keeps (State.config)."""
        return {setting.name: setting.value for setting in self.settings()}


# The settings: Config's properties, in the order written.
_PROPERTIES = {name: member for name, member in vars(Config).items() if isinstance(member, property)}
_NAMES = tuple(_PROPERTIES)
_TYPES = {name: typing.get_type_hints(member.fget)["return"] for name, member in _PROPERTIES.items()}
_ABOUT = {name: " ".join((member.fget.__doc__ or "").split()) for name, member in _PROPERTIES.items()}


def _text(value: Any) -> str:
    """A value as the form and the file show it; a path under $HOME starts with ~, so the file
    works on every machine.
    """
    if isinstance(value, Path):
        home = str(Path.home())
        return "~" + str(value)[len(home) :] if str(value).startswith(home + "/") else str(value)
    return str(value)


def _toml(value: Any) -> str:
    """A value as TOML: numbers and booleans as they are, anything else a quoted string."""
    if isinstance(value, bool):
        return "true" if value else "false"
    if isinstance(value, int | float):
        return str(value)
    return json.dumps(_text(value))


def _typed(name: str, value: Any) -> Any:
    """A given value as the setting's type, checked (its own check_<name> too). None or "" =
    not set. Raises ValueError saying why a value is refused.
    """
    if value is None or value == "":
        return None
    try:
        typed = TypeAdapter(_TYPES[name]).validate_python(value)
    except ValidationError as error:
        raise ValueError("; ".join(e["msg"] for e in error.errors())) from error
    if isinstance(typed, Path):
        typed = typed.expanduser()
    if check := getattr(Config, f"check_{name}", None):
        check(config, typed)
    return typed


config = Config()

# What set_config gives back: every setting's value in use, as text (a model, so it shows as
# the Fields widget and the Config widget's form finds it).
ConfigValues: type[BaseModel] = create_model("ConfigValues", **{name: (str, ...) for name in _NAMES})


def set_config(**changes: Any) -> BaseModel:
    """Change the app's settings (see the generated docstring below)."""
    unknown = [name for name in changes if name not in _NAMES]
    if unknown:
        raise ValueError(f"not a setting: {', '.join(unknown)}")
    problems, typed = [], {}
    for name, value in changes.items():
        try:
            typed[name] = _typed(name, value)
        except ValueError as error:
            problems.append(f"{name}: {error}")
    if problems:  # nothing is changed unless every value is fine
        raise ValueError("; ".join(problems))
    config.load()
    for name, value in typed.items():
        config._set(name, value)  # noqa: SLF001  # this module's own class
    config.save()
    return ConfigValues(**config.texts())


# set_config's inputs are the settings: one optional parameter each, described by its
# property's docstring. tool_forms.ToolForm reads this signature as it does an agent tool's,
# which gives the Config widget its form (and the inline AI its output shape) with no code
# per setting.
set_config.__signature__ = inspect.Signature(  # type: ignore[attr-defined]
    [
        inspect.Parameter(name, inspect.Parameter.KEYWORD_ONLY, default=None, annotation=_TYPES[name] | None)
        for name in _NAMES
    ],
    return_annotation=ConfigValues,
)
set_config.__annotations__ = {**{name: _TYPES[name] | None for name in _NAMES}, "return": ConfigValues}
set_config.__doc__ = "\n".join(
    [
        "Change the app's settings. An input left empty puts that setting back on its default.",
        "",
        "Args:",
        *[f"    {name}: {_ABOUT[name]}" for name in _NAMES],
    ]
)
